diff --git a/tools/compare-editors.sh b/tools/compare-editors.sh
index 2431d2b..d06b504 100755
--- a/tools/compare-editors.sh
+++ b/tools/compare-editors.sh
@@ -145,7 +145,7 @@ phase_args() {
     main) echo "artisan://thread/$HOST_ID/$LARGE" ;;
     open) echo "artisan://new/$HOST_ID" ;;
     stream|streamprof) echo "artisan://thread/$HOST_ID/$STREAM" ;;
-    wakesrc|spikes|memdiag|idlegate|idleprobe|resize|resizeprof|cold|coldprof) echo "artisan://thread/$HOST_ID/$LARGE" ;;
+    capture|wakesrc|spikes|memdiag|idlegate|idleprobe|resize|resizeprof|cold|coldprof) echo "artisan://thread/$HOST_ID/$LARGE" ;;
   esac
 }

@@ -172,6 +172,9 @@ phase_steps() {
       [ "${AQUA_COMPARE_GATE_CONTROL:-0}" = 1 ] && poke="wheel $SCROLL_X $SCROLL_Y -120; "
       echo "waitopen $LARGE 45 $SIDEBAR_THREAD 30; sleep 8; ${poke}wakelines idle_gate $GATE_IDLE_SECONDS"
       ;;
+    capture)
+      echo "waitopen $LARGE 45 $SIDEBAR_THREAD 30; sleep 8; capturebench capture 3"
+      ;;
     memdiag)
       echo "waitopen $LARGE 45 $SIDEBAR_THREAD 30; sleep 4; gpumem boot; scrolllat mem_scroll $SCROLL_X $SCROLL_Y $SCROLL_FRAMES $SCROLL_GAP_MS 120; sleep 5; gpumem settle"
       ;;
