+        printed = PrintWindow(h, dc, flags);
         g.ReleaseHdc(dc);
       }
       Rectangle rc = new Rectangle(o.X - wr.L, o.Y - wr.T, cw, ch);
       BitmapData d = full.LockBits(rc, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
-      Frame f = new Frame(); f.W = cw; f.H = ch; f.Px = new byte[cw * ch * 4];
+      Frame f = new Frame(); f.W = cw; f.H = ch; f.Px = new byte[cw * ch * 4]; f.Printed = printed;
       for (int y = 0; y < ch; y++) Marshal.Copy(IntPtr.Add(d.Scan0, y * d.Stride), f.Px, y * cw * 4, cw * 4);
       full.UnlockBits(d);
       return f;
@@ -468,6 +470,24 @@ function Probe-Latency($name, $kind, $count, $gap, $scroll, $x, $y, $delta) {
           "probe-gpumem name=$($a[0]) dedicated_mb=$([math]::Round($sum/1MB,1))"
         } catch { "probe-gpumem name=$($a[0]) unavailable=$($_.Exception.Message)" }
       }
+      "capturebench" {
+        $captureCount = [int]$a[1]
+        if ($captureCount -le 0 -or $captureCount -gt 20) { throw "capturebench needs 1 to 20 samples" }
+        $captureBaseline = [W]::Grab($h)
+        if ($null -eq $captureBaseline -or -not $captureBaseline.Printed -or [W]::NonDominant($captureBaseline) -le 0.06) { throw "capturebench requires a nonempty reference frame" }
+        "probe-capture-reference name=$($a[0]) width=$($captureBaseline.W) height=$($captureBaseline.H) nondominant=$([math]::Round([W]::NonDominant($captureBaseline),4))"
+        for ($captureIndex = 0; $captureIndex -lt $captureCount; $captureIndex++) {
+          foreach ($captureFlags in @(0, 2)) {
+            $captureClock = [System.Diagnostics.Stopwatch]::StartNew()
+            $captureFrame = [W]::Grab($h, [uint32]$captureFlags)
+            $captureMs = $captureClock.Elapsed.TotalMilliseconds
+            if ($null -eq $captureFrame) { throw "capturebench window has no client area" }
+            $captureChanged = [W]::ChangedPixels($captureBaseline, $captureFrame, 0, 0, $captureFrame.W, $captureFrame.H)
+            $captureTotal = $captureFrame.W * $captureFrame.H
+            "probe-capture name=$($a[0]) sample=$captureIndex flags=$captureFlags printed=$($captureFrame.Printed) elapsed_ms=$([math]::Round($captureMs,3)) changed_pixels=$captureChanged total_pixels=$captureTotal changed_pct=$([math]::Round(100.0 * $captureChanged / $captureTotal,4)) nondominant=$([math]::Round([W]::NonDominant($captureFrame),4))"
+          }
+        }
+      }
       "snapshot" { $frames[$a[0]] = [W]::Grab($h) }
